<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DNA Double Helix</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    background: #0a0a12;
    overflow: hidden;
  }
  canvas {
    display: block;
    width: 100vw;
    height: 100vh;
  }
</style>
</head>
<body>
<canvas id="dna"></canvas>
<script>
(function () {
  'use strict';

  const canvas = document.getElementById('dna');
  const ctx = canvas.getContext('2d');

  let W, H, cx;
  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    cx = W / 2;
  }
  window.addEventListener('resize', resize);
  resize();

  // Helix parameters
  const NODES = 60;          // nodes per strand
  const SEGMENT_GAP = 14;    // vertical spacing between nodes
  const AMPLITUDE = Math.min(window.innerWidth, window.innerHeight) * 0.28;
  const WAVE_LENGTH = 260;   // pixels per full twist
  const SPEED = 0.012;       // rotation speed
  const NODE_R = 4.5;

  // Colors
  const STRAND_A = [90, 200, 255];
  const STRAND_B = [255, 120, 180];
  const BG = '#0a0a12';

  function strandColor(base, depth) {
    // depth 0 (near) .. 1 (far): dim far nodes
    const f = 1 - depth * 0.75;
    return 'rgb(' +
      Math.round(base[0] * f) + ',' +
      Math.round(base[1] * f) + ',' +
      Math.round(base[2] * f) + ')';
  }

  function draw(time) {
    const phase = time * SPEED;

    // Background
    ctx.fillStyle = BG;
    ctx.fillRect(0, 0, W, H);

    const totalH = NODES * SEGMENT_GAP;
    const top = (H - totalH) / 2;

    // Build node data for both strands
    const nodesA = [];
    const nodesB = [];
    for (let i = 0; i < NODES; i++) {
      const y = top + i * SEGMENT_GAP;
      const ang = phase + (y / WAVE_LENGTH) * Math.PI * 2;
      const dx = Math.cos(ang) * AMPLITUDE;
      const depth = (Math.sin(ang) + 1) / 2; // 0 far .. 1 near
      nodesA.push({ x: cx + dx, y: y, d: depth, ang: ang });
      nodesB.push({ x: cx - dx, y: y, d: 1 - depth, ang: ang + Math.PI });
    }

    // Draw rungs (base pairs) first, then strands on top.
    // Draw far-to-near for painter's ordering.
    const order = [];
    for (let i = 0; i < NODES; i++) order.push(i);
    order.sort(function (a, b) {
      return nodesA[a].d - nodesA[b].d;
    });

    for (const i of order) {
      const a = nodesA[i];
      const b = nodesB[i];
      const near = Math.max(a.d, b.d);

      // Rung line
      const rungAlpha = 0.25 + near * 0.45;
      const rg = Math.round(140 + near * 80);
      ctx.strokeStyle = 'rgba(' + rg + ',' + rg + ',' + Math.round(rg + 20) + ',' + rungAlpha.toFixed(3) + ')';
      ctx.lineWidth = 1 + near * 2;
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();

      // Rung midpoint tick (base pair hint)
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;
      ctx.fillStyle = 'rgba(200,220,255,' + (0.15 + near * 0.3).toFixed(3) + ')';
      ctx.beginPath();
      ctx.arc(mx, my, 1.5 + near * 1.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw strands: for each strand, connect consecutive nodes with lines,
    // painter-sorted by depth so near segments overlap far ones.
    function drawStrand(nodes, base) {
      const idx = [];
      for (let i = 0; i < NODES - 1; i++) idx.push(i);
      idx.sort(function (a, b) {
        return (nodes[a].d + nodes[a + 1].d) / 2 - (nodes[b].d + nodes[b + 1].d) / 2;
      });
      for (const i of idx) {
        const p = nodes[i];
        const q = nodes[i + 1];
        const d = (p.d + q.d) / 2;
        ctx.strokeStyle = strandColor(base, 1 - d);
        ctx.lineWidth = 1.5 + d * 2.5;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(q.x, q.y);
        ctx.stroke();
      }
      // Nodes
      const nidx = [];
      for (let i = 0; i < NODES; i++) nidx.push(i);
      nidx.sort(function (a, b) { return nodes[a].d - nodes[b].d; });
      for (const i of nidx) {
        const p = nodes[i];
        ctx.fillStyle = strandColor(base, 1 - p.d);
        ctx.beginPath();
        ctx.arc(p.x, p.y, NODE_R * (0.5 + p.d * 0.8), 0, Math.PI * 2);
        ctx.fill();
      }
    }

    drawStrand(nodesA, STRAND_A);
    drawStrand(nodesB, STRAND_B);

    requestAnimationFrame(draw);
  }

  requestAnimationFrame(draw);
})();
</script>
</body>
</html>
